import { test, expect } from '@playwright/test';

import generatedUsers
  from '../../data/mocks/generated-users.json';

test(
  'mock users generated by python',
  async ({ page }) => {

    await page.route(
      'https://reqres.in/api/users*',
      async route => {

        await route.fulfill({

          status: 200,

          contentType:
            'application/json',

          body: JSON.stringify(
            generatedUsers
          )

        });

      }
    );

    const response =
      await page.evaluate(
        async () => {

          const response =
            await fetch(
              'https://reqres.in/api/users?page=2'
            );

          return await response.json();

        }
      );

    expect(
      response.data.length
    ).toBe(5);

    expect(
      response.data[0].email
    ).toBe(
      'user1@example.com'
    );

  }
);